CREATE TABLE IF NOT EXISTS crm_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text NOT NULL DEFAULT '', assigned_to uuid NOT NULL REFERENCES service_employees(id), created_by uuid NOT NULL REFERENCES service_employees(id), priority text NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done','cancelled')), due_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS crm_tasks_assignee_idx ON crm_tasks(assigned_to,status,due_at);
